import yargs from 'yargs';
import { hideBin } from 'yargs/helpers';
import { g as generate, l as loadSchema, v as validateJson } from './shared/api-gen.BZLmrTCs.mjs';
import 'node:fs';
import 'node:path';
import 'openapi-typescript';
import 'typescript';
import 'ofetch';
import 'prettier';
import 'ts-morph';
import 'fs';
import 'path';
import 'os';
import 'crypto';
import '@shopware/api-client';

const name = "@shopware/api-gen";
const version = "1.3.3";
const description = "Shopware CLI for API client generation.";
const author = "Shopware";
const type = "module";
const repository = {
	type: "git",
	url: "git+https://github.com/shopware/frontends.git"
};
const homepage = "https://frontends.shopware.com/packages/api-client.html";
const keywords = [
	"shopware",
	"api",
	"client",
	"cli"
];
const bugs = {
	url: "https://github.com/shopware/frontends/issues"
};
const license = "MIT";
const exports = {
	".": {
		types: "./dist/index.d.ts",
		"import": "./dist/index.mjs"
	}
};
const files = [
	"bin",
	"dist"
];
const bin = {
	"api-gen": "bin/api-gen.mjs",
	"shopware-api-gen": "bin/api-gen.mjs"
};
const scripts = {
	build: "unbuild",
	cli: "esno ./src/cli.ts",
	dev: "export NODE_ENV=development && unbuild --stub",
	lint: "biome check .",
	"lint:fix": "biome check --write . && pnpm run typecheck",
	typecheck: "tsc --noEmit",
	test: "vitest run --typecheck",
	"test:bench": "vitest bench",
	"test:watch": "vitest --typecheck"
};
const devDependencies = {
	"@biomejs/biome": "1.8.3",
	"@types/prettier": "3.0.0",
	"@types/yargs": "17.0.33",
	"@vitest/coverage-v8": "3.2.4",
	json5: "2.2.3",
	picocolors: "1.1.1",
	tsconfig: "workspace:*",
	unbuild: "2.0.0",
	vitest: "3.2.4"
};
const dependencies = {
	"@shopware/api-client": "workspace:*",
	ofetch: "1.4.1",
	"openapi-typescript": "7.8.0",
	prettier: "3.6.2",
	"ts-morph": "26.0.0",
	typescript: "5.9.2",
	yargs: "18.0.0"
};
const packageJson = {
	name: name,
	version: version,
	description: description,
	author: author,
	type: type,
	repository: repository,
	homepage: homepage,
	keywords: keywords,
	bugs: bugs,
	license: license,
	exports: exports,
	files: files,
	bin: bin,
	scripts: scripts,
	devDependencies: devDependencies,
	dependencies: dependencies
};

function commonOptions(args) {
  return args.option("cwd", {
    alias: "C",
    default: process.cwd(),
    type: "string",
    describe: "specify the current working directory"
  });
}
yargs(hideBin(process.argv)).scriptName("@shopware/api-gen").usage("$0 [args]").command(
  "generate",
  "Generate schema from your API instance",
  (args) => {
    return commonOptions(args).positional("filename", {
      type: "string",
      describe: "name of the file to generate type from. The default (based on apiType parameter) is 'storeApiSchema.json' or 'adminApiSchema.json'"
    }).option("apiType", {
      choices: ["store", "admin"],
      demandOption: true,
      describe: "type of the generated API. Values: store, admin"
    }).positional("debug", {
      type: "boolean",
      default: false,
      describe: "show debug information and generate intermediate files"
    }).option("logPatches", {
      type: "boolean",
      default: false,
      describe: "show patched logs"
    }).help();
  },
  async (args) => generate(args)
).command(
  "loadSchema",
  "Load JSON schema from your API instance. You need to have proper .env file",
  (args) => {
    return commonOptions(args).option("apiType", {
      describe: "Type of the API schema to load. It can be 'store' or 'admin'",
      demandOption: true,
      choices: ["store", "admin"]
    }).positional("filename", {
      type: "string",
      describe: "name of the file to save schema. The default (based on apiType parameter) is 'storeApiSchema.json' or 'adminApiSchema.json'"
    }).help();
  },
  async (args) => loadSchema(args)
).command(
  "validateJson",
  "Validate JSON schema with the ruleset",
  (args) => {
    return commonOptions(args).option("apiType", {
      describe: "Type of the API schema to load. It can be 'store' or 'admin'",
      demandOption: true,
      choices: ["store", "admin"]
    }).positional("filename", {
      type: "string",
      describe: "name of the schema json file. The default (based on apiType parameter) is 'storeApiSchema.json' or 'adminApiSchema.json'"
    }).option("logPatches", {
      type: "boolean",
      default: false,
      describe: "show patched logs"
    }).positional("debug", {
      type: "boolean",
      default: false,
      describe: "show debug information and generate intermediate files"
    }).help();
  },
  async (args) => validateJson(args)
).showHelpOnFail(false).alias("h", "help").version("version", packageJson.version).alias("v", "version").help().argv;
